// Versie 1.5.4
// Tolerante verwerking van AI-JSON.
// Herstelt uitsluitend bekende syntactische afwijkingen:
// - markdown code fences;
// - tekst vóór/na het JSON-object;
// - ongeldige control characters binnen strings;
// - trailing comma vóór ] of };
// - ontbrekende afsluitende ] of } bij een afgebroken einde.
// De inhoudelijke scores en matches worden niet aangepast.

const inputItems = $input.all();
const output = [];

function verwijderCodeFences(value = '') {
  return String(value)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function haalJsonBereikOp(value = '') {
  const tekst = String(value);
  const objectStart = tekst.indexOf('{');
  const arrayStart = tekst.indexOf('[');

  let start = -1;

  if (objectStart === -1) {
    start = arrayStart;
  } else if (arrayStart === -1) {
    start = objectStart;
  } else {
    start = Math.min(objectStart, arrayStart);
  }

  if (start === -1) {
    return tekst.trim();
  }

  let inString = false;
  let escaped = false;
  const stack = [];

  for (let i = start; i < tekst.length; i++) {
    const char = tekst[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === '\\') {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === '{' || char === '[') {
      stack.push(char);
      continue;
    }

    if (char === '}' || char === ']') {
      const verwacht = char === '}' ? '{' : '[';

      if (stack[stack.length - 1] === verwacht) {
        stack.pop();

        if (stack.length === 0) {
          return tekst.slice(start, i + 1).trim();
        }
      }
    }
  }

  // Bij afgebroken AI-output het beschikbare JSON-gedeelte teruggeven.
  return tekst.slice(start).trim();
}

function escapeControlCharactersInStrings(value = '') {
  let resultaat = '';
  let inString = false;
  let escaped = false;

  for (const char of String(value)) {
    if (inString) {
      if (escaped) {
        resultaat += char;
        escaped = false;
        continue;
      }

      if (char === '\\') {
        resultaat += char;
        escaped = true;
        continue;
      }

      if (char === '"') {
        resultaat += char;
        inString = false;
        continue;
      }

      const code = char.charCodeAt(0);

      if (code >= 0 && code <= 31) {
        if (char === '\n') resultaat += '\\n';
        else if (char === '\r') resultaat += '\\r';
        else if (char === '\t') resultaat += '\\t';
        else resultaat += `\\u${code.toString(16).padStart(4, '0')}`;
        continue;
      }

      resultaat += char;
      continue;
    }

    resultaat += char;

    if (char === '"') {
      inString = true;
    }
  }

  return resultaat;
}

function verwijderTrailingCommas(value = '') {
  return String(value).replace(/,\s*([}\]])/g, '$1');
}

function sluitOpenStructuren(value = '') {
  const tekst = String(value).trim();
  let inString = false;
  let escaped = false;
  const stack = [];

  for (const char of tekst) {
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === '\\') {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
    } else if (char === '{' || char === '[') {
      stack.push(char);
    } else if (char === '}' && stack[stack.length - 1] === '{') {
      stack.pop();
    } else if (char === ']' && stack[stack.length - 1] === '[') {
      stack.pop();
    }
  }

  let hersteld = tekst;

  // Een werkelijk afgebroken string wordt niet inhoudelijk gegokt.
  // Alleen een afsluitend aanhalingsteken toevoegen als het einde
  // duidelijk midden in een JSON-string ligt.
  if (inString) {
    hersteld += '"';
  }

  while (stack.length > 0) {
    const open = stack.pop();
    hersteld += open === '{' ? '}' : ']';
  }

  return hersteld;
}

function parseAiJson(rawValue) {
  if (rawValue !== null && typeof rawValue === 'object') {
    return {
      parsed: rawValue,
      herstelMethode: 'object_reeds_geldig'
    };
  }

  if (typeof rawValue !== 'string' || rawValue.trim() === '') {
    throw new Error('Geen geldige JSON-tekst ontvangen.');
  }

  const basis = haalJsonBereikOp(verwijderCodeFences(rawValue));

  const pogingen = [
    {
      naam: 'origineel',
      waarde: basis
    },
    {
      naam: 'control_characters',
      waarde: escapeControlCharactersInStrings(basis)
    },
    {
      naam: 'control_characters_en_trailing_comma',
      waarde: verwijderTrailingCommas(
        escapeControlCharactersInStrings(basis)
      )
    },
    {
      naam: 'structuur_afgesloten',
      waarde: sluitOpenStructuren(
        verwijderTrailingCommas(
          escapeControlCharactersInStrings(basis)
        )
      )
    }
  ];

  const unieke = new Set();
  let laatsteFout = null;

  for (const poging of pogingen) {
    if (!poging.waarde || unieke.has(poging.waarde)) {
      continue;
    }

    unieke.add(poging.waarde);

    try {
      return {
        parsed: JSON.parse(poging.waarde),
        herstelMethode: poging.naam
      };
    } catch (error) {
      laatsteFout = error;
    }
  }

  throw new Error(
    `Ongeldige JSON na gecontroleerd herstel: ${
      laatsteFout?.message || 'onbekende parsefout'
    }. Begin van de invoer: ${basis.slice(0, 500)}`
  );
}

function heeftVacatureData(obj) {
  return Boolean(
    obj &&
    (
      obj.vacatureTitel ||
      obj.vacatureUrl ||
      obj.vacatureTekst
    )
  );
}

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const input = item.json || {};

  const rawValue =
    input.output ??
    input.text ??
    input.content ??
    input.response ??
    input.body ??
    input;

  const parseResultaat = parseAiJson(rawValue);
  const parsed = parseResultaat.parsed;

  let bron = {};

  try {
    const m = $('Code-Validatie vacature').itemMatching(i);
    if (heeftVacatureData(m?.json)) bron = m.json;
  } catch (e) {}

  try {
    const m = $('Code-Titel + Tekst + URL').itemMatching(i);
    if (heeftVacatureData(m?.json)) bron = m.json;
  } catch (e) {}

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Circle8 e-mail naar vacature').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Staffinggroep e-mail naar vacature').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-DPP detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-BlueTrail detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Yacht detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-MiPublic detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Striive detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }
  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Hero detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }
  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-ZZP detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-FlexSpot detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Seven Stars resultaten').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-BlueTrail geldige details').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-Titel + Tekst + URL').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-Circle8 e-mail naar vacature').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-Staffinggroep e-mail naar vacature').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-DPP detail').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-BlueTrail detail').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-Yacht detail').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-MiPublic detail').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-Striive detail').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }


  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Funle resultaten').itemMatching(i);
      if (heeftVacatureData(m?.json)) bron = m.json;
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const items = $('Code-BlueTrail geldige details').all();
      if (heeftVacatureData(items[i]?.json)) bron = items[i].json;
    } catch (e) {}
  }

  const vacatureHtml = parsed?.vacatureHtml ?? '';
  const medewerkers = Array.isArray(parsed?.medewerkers)
    ? parsed.medewerkers
    : [];

  for (const medewerker of medewerkers) {
    output.push({
      json: {
        medewerker: medewerker?.naam ?? '',
        score: Number(medewerker?.score ?? 0),
        gevondenKeywords: Array.isArray(medewerker?.gevondenKeywords)
